function organRibbon(){return `<div class="organ-ribbon" role="group" aria-label="${T('Select an organ','اختر عضواً')}">${Object.entries(findings).map(([id,d],i)=>`<button class="organ-chip ${state.organ===id?'active':''}" data-organ="${id}" aria-pressed="${state.organ===id}"><span class="organ-icon">${icon(id)}</span><span class="organ-chip-copy"><strong>${L(d.short)}</strong><small>${L(d.status)}</small></span><span class="chip-index">0${i+1}</span></button>`).join('')}</div>`;}

