function ctPanel(){const p=ctMetadata.previews[state.slice];return `<div class="ct-image-card"><div class="ct-image-header"><span>${T('AXIAL PREVIEW','مقطع محوري')}</span><span id="slice-number">${state.slice+1} / 12</span></div><img id="ct-preview" src="./assets/ct/${p.file}" alt="${T('Original CT axial slice, unannotated','مقطع محوري أصلي غير معلّم')}"><input id="ct-slice" class="ct-slider" aria-label="${T('Browse CT slices','تصفح مقاطع التصوير')}" type="range" min="0" max="11" value="${state.slice}"><div class="ct-caption" id="ct-caption">${ctCaption()}</div></div>
 <div class="finding-card"><div class="card-top"><span class="card-index">${T('SOURCE STUDY','الدراسة الأصلية')}</span><span class="status">02 SEP 2026</span></div><h2>${T('Inside the scan','داخل التصوير')}</h2><p class="finding-diagnosis" style="margin-top:15px">${T('A reconstruction of Husam’s actual CT coverage: lower chest, abdomen, pelvis and upper thighs.','إعادة بناء لمنطقة الفحص الفعلية لحسام: أسفل الصدر والبطن والحوض وأعلى الفخذين.')}</p><div class="metric-grid"><div><span class="metric-label">${T('Selected series','السلسلة المحددة')}</span><span class="metric-value">98</span> <span class="metric-unit">${T('slices','مقطعاً')}</span></div><div><span class="metric-label">${T('Slice spacing','تباعد المقاطع')}</span><span class="metric-value">5</span> <span class="metric-unit">mm</span></div></div><h3 class="mini-title">${T('Surface layers','طبقات السطح')}</h3><div class="ct-layer-buttons">${['both','body','bone'].map(v=>`<button data-layer="${v}" class="${state.ctLayer===v?'active':''}">${v==='both'?T('Combined','معاً'):v==='body'?T('Body','الجسم'):T('Dense tissue','نسيج كثيف')}</button>`).join('')}</div><p class="function-note">${T('Dense tissue is extracted at 300 HU and can include structures other than bone. No tumor or organ segmentation was performed.','استُخرج النسيج الكثيف بعتبة 300 HU وقد يشمل تراكيب غير عظمية. لم تُحدد الأورام أو الأعضاء من الصور.')}</p><a class="source-link" href="./assets/ct/metadata.json" target="_blank" rel="noopener" style="margin-top:17px">${icon('file')}${T('View reconstruction provenance','عرض بيانات مصدر البناء')}${icon('arrow')}</a></div>
 <div class="info-card"><h3>${icon('info')}${T('Reading the preview','قراءة المقاطع')}</h3><p>${T('The slider moves through 12 sampled slices, from upper to lower anatomy. The line in the 3D view marks the slice height. Fixed soft-tissue window; illustrative, not a diagnostic DICOM viewer.','ينتقل الشريط بين 12 مقطعاً مختاراً من الأعلى للأسفل. يحدد الخط في النموذج مستوى المقطع. نافذة الأنسجة ثابتة وهذا عرض توضيحي وليس قارئ DICOM تشخيصياً.')}</p></div>`;}

